"""Quality + license filters for pretraining documents."""
from __future__ import annotations

PERMISSIVE = {"MIT", "Apache-2.0", "BSD-2-Clause", "BSD-3-Clause"}

_AUTOGEN_MARKERS = ("auto-generated", "autogenerated", "automatically generated", "do not edit",
                    "generated by the protocol buffer compiler", "generated by django")


def license_ok(licenses) -> bool:
    """True only if the file's repo licenses are all in the MIT/Apache/BSD set."""
    if licenses is None:
        return False
    if isinstance(licenses, str):
        licenses = [licenses]
    licenses = list(licenses)
    return bool(licenses) and all(l in PERMISSIVE for l in licenses)


def python_quality_reason(content: str, row: dict | None = None) -> str | None:
    """Returns a rejection reason, or None if the file is kept. Uses the-stack's precomputed
    stats when available (cheap), otherwise computes them."""
    n = len(content)
    if n < 64:
        return "too_short"
    if n > 200_000:
        return "too_long"
    if row is not None and row.get("max_line_length") is not None:
        max_line, avg_line, alnum = row["max_line_length"], row["avg_line_length"], row["alphanum_fraction"]
    else:
        lines = content.splitlines() or [""]
        max_line = max(len(l) for l in lines)
        avg_line = n / len(lines)
        alnum = sum(c.isalnum() for c in content) / n
    if max_line > 1000:
        return "long_line"
    if avg_line > 100:
        return "avg_line"
    if alnum < 0.25:
        return "alnum"
    head = content[:600].lower()
    if any(m in head for m in _AUTOGEN_MARKERS):
        return "autogenerated"
    return None
